import sys, json, re, subprocess, time, os, urllib.request
sys.path.insert(0, "/home/joshua/llm/voice-loop/multiplex")
import multiplex, blackboard

MPX = "/home/joshua/llm/voice-loop/multiplex"
GOAL = ("Produce a briefing file that names today's warmest city among "
        "Columbus, Cleveland and Cincinnati (Ohio), lists all three "
        "current temperatures, and states the temperature spread - "
        "generated by code from live weather data.")
CITIES = {"Columbus": (39.9612, -82.9988), "Cleveland": (41.4993, -81.6944),
          "Cincinnati": (39.1031, -84.5120)}
t0 = time.time()
scores = {}

# ---- Stage A: live findings (real data)
findings = {}
for city, (la, lo) in CITIES.items():
    url = (f"https://api.open-meteo.com/v1/forecast?latitude={la}"
           f"&longitude={lo}&current=temperature_2m")
    with urllib.request.urlopen(url, timeout=30) as r:
        d = json.load(r)
    findings[city] = {"temp_c": d["current"]["temperature_2m"]}
findings_path = f"{MPX}/out/hard2-findings.json"
json.dump(findings, open(findings_path, "w"), indent=1)
blackboard.write("findings", "hard2-weather", findings)
warmest = max(findings, key=lambda c: findings[c]["temp_c"])
print("STAGE A findings:", findings, "| warmest:", warmest)

# ---- Stage B: verified findings brief (duplex stage 1)
b_prompt = ("Turn this live weather data into a 3-4 sentence findings "
            "brief. State each city's temperature exactly as given, "
            "name the warmest city, and give the spread between warmest "
            "and coldest. Data:\n" + json.dumps(findings))
b = multiplex.run_verified(
    "quicklook", b_prompt,
    criteria="All three temperatures exactly match the data; warmest "
             "city correct; spread arithmetic correct.",
    max_tokens=300)
scores["stageB_brief"] = b.get("score")
print("STAGE B score:", b.get("score"), "verified:", b.get("verified"),
      "| brief:", b.get("text", "")[:200].replace("\n", " "))

# ---- Stage C: code writes the briefing generator (duplex stage 2)
c_prompt = f"""Write a complete Python script and output ONLY the code.

The script must:
1. Read the JSON file {findings_path} (format: {{"City": {{"temp_c": number}}, ...}}).
2. Compute the warmest city, the coldest city, and the temperature spread.
3. Write a Markdown briefing to {MPX}/out/hard2-briefing.md containing: a title line, one line per city with its temperature, a line naming the warmest city, and a line with the spread.
4. Print the briefing to stdout.

Output only the Python code, in a single ```python block."""
c = multiplex.run_verified(
    "code", c_prompt,
    criteria="Script reads the given JSON path, computes warmest/coldest/"
             "spread from the data (no hardcoded temperatures), writes "
             "the briefing markdown to the given output path.",
    max_tokens=1100)
scores["stageC_code"] = c.get("score")
code_text = c.get("text", "")
m = re.search(r"```(?:python)?\s*\n(.*?)```", code_text, re.DOTALL)
code = m.group(1) if m else code_text
script_path = f"{MPX}/out/hard2-gen.py"
open(script_path, "w").write(code)
print("STAGE C score:", c.get("score"), "verified:", c.get("verified"),
      "| script bytes:", os.path.getsize(script_path))

# ---- Stage D: run it, grade the artifact (duplex stage 3)
briefing_path = f"{MPX}/out/hard2-briefing.md"
if os.path.exists(briefing_path):
    os.remove(briefing_path)
run = subprocess.run([sys.executable, script_path], capture_output=True,
                     text=True, timeout=60)
print("STAGE D run rc:", run.returncode, "| stderr:", run.stderr[:200])
briefing = ""
if os.path.exists(briefing_path):
    briefing = open(briefing_path).read()
print("briefing:\n", briefing[:500])
d_score = multiplex.verify(GOAL, briefing) if briefing else None
scores["stageD_briefing"] = d_score
print("STAGE D artifact score:", d_score)

temps_in = all(str(findings[c]["temp_c"]) in briefing for c in CITIES)
warmest_in = warmest in briefing and "warm" in briefing.lower()
ok = (run.returncode == 0 and briefing and temps_in and warmest_in
      and d_score is not None)
print("CHECKS", {"temps_all_present": temps_in, "warmest_named": warmest_in,
                 "scores": scores})
print("WALL", round(time.time() - t0, 1))
print("HARD2", "PASS" if ok else "FAIL")
